2800 static bool inSubLoop(BasicBlock *BB, Loop *CurLoop, LoopInfo *LI) {
2801   assert(CurLoop->contains(BB) && "Only valid if BB is IN the loop");
2802   return LI->getLoopFor(BB) != CurLoop;
